from shop.util import fmt
class Cart:
    def __init__(self): self.items=[]
    def add(self,n,p,q=1): self.items.append((n,p,q))
    def total(self):
        t=0
        for n,p,q in self.items: t+=p*q
        return t
    def show(self): return fmt(self.total())

