cd /workspace; python3 - <<'EOF'
import ast, pathlib
missing=[]
for p in sorted(pathlib.Path("shop").glob("*.py")):
    tree=ast.parse(p.read_text())
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
            a=[x for x in n.args.args if x.arg not in {"self","cls"}]+n.args.kwonlyargs
            bad=[x.arg for x in a if x.annotation is None]
            if bad or n.returns is None: missing.append(f"{p}:{n.lineno} {n.name} {bad}")
print("unannotated functions:", missing or "NONE - all fully annotated")
EOF
